use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

struct Node;

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn render(d: &Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(&d.date);
    msg.push_str("\n\n");
    if !d.overview.is_empty() {
        msg.push_str(&d.overview);
        msg.push_str("\n\n");
    }

    let mut entries: Vec<_> = d.entries.iter().filter(|e| e.kept).collect();
    entries.sort_by_key(|e| importance_rank(e.importance));

    if entries.is_empty() {
        msg.push_str("No items made the digest today.\n");
    } else {
        for e in entries {
            msg.push_str("- [");
            msg.push_str(importance_label(e.importance));
            msg.push_str(" / ");
            msg.push_str(category_label(e.category));
            msg.push_str("] ");
            msg.push_str(&e.title);
            msg.push_str(" (");
            msg.push_str(&e.feed);
            msg.push_str(")\n  ");
            msg.push_str(&e.link);
            msg.push('\n');
            if !e.summary.is_empty() {
                msg.push_str("  ");
                msg.push_str(&e.summary);
                msg.push('\n');
            }
        }
    }

    msg.push_str("\n");
    msg.push_str(&d.considered.len().to_string());
    msg.push_str(" items considered.\n");
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch, as directed by the graph author. Side effect only:
        // the result (success or transport failure) is deliberately discarded
        // so the node's output is unchanged.
        let url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&composed.overview));
        let _ = http_client::fetch(&url);

        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

